import React from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';

const Header: React.FC = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const { user, logout } = useAuth();

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  const isActive = (path: string) => location.pathname === path;

  return (
    <div style={styles.header}>
      <div style={styles.container}>
        {/* Логотип слева */}
        <Link to="/" style={styles.logoLink}>
          <div style={styles.logo}>
            ЦЕНЗУРА ПД
          </div>
        </Link>

        {/* Центральная навигация - ОГРОМНЫЕ кнопки */}
        <div style={styles.centerNav}>
          <Link 
            to="/" 
            style={{
              ...styles.megaButton,
              ...(isActive('/') ? styles.activeMegaButton : {})
            }}
          >
            <span style={styles.megaIcon}>🏠</span>
            <span style={styles.megaText}>ГЛАВНАЯ</span>
          </Link>
          
          {user && (
            <Link 
              to="/redaction" 
              style={{
                ...styles.megaButton,
                ...(isActive('/redaction') ? styles.activeMegaButton : {})
              }}
            >
              <span style={styles.megaIcon}>🖼️</span>
              <span style={styles.megaText}>РЕДАКТОР</span>
            </Link>
          )}
        </div>

        {/* Правая часть */}
        <div style={styles.rightSection}>
          {/* Кнопка "О проекте" */}
          <Link 
            to="/about" 
            style={{
              ...styles.smallButton,
              ...(isActive('/about') ? styles.activeSmallButton : {})
            }}
          >
            <span style={styles.smallIcon}>ℹ️</span>
            <span style={styles.smallText}>О проекте</span>
          </Link>

          {/* Блок пользователя или кнопки авторизации */}
          {user ? (
            <div style={styles.userBlock}>
              <div style={styles.userInfo}>
                <span style={styles.userIcon}>{user.is_admin ? '👑' : '👤'}</span>
                <span style={styles.userName}>{user.username}</span>
                {user.is_admin && <span style={styles.adminTag}>ADMIN</span>}
              </div>
              <div style={styles.userActions}>
                <button 
                  onClick={() => navigate('/profile')}
                  style={styles.profileButton}
                >
                  ПРОФИЛЬ
                </button>
                <button 
                  onClick={handleLogout}
                  style={styles.logoutButton}
                >
                  ВЫЙТИ
                </button>
              </div>
            </div>
          ) : (
            <div style={styles.authButtons}>
              <Link 
                to="/login" 
                style={{
                  ...styles.smallButton,
                  ...(isActive('/login') ? styles.activeSmallButton : {})
                }}
              >
                <span style={styles.smallIcon}>🔐</span>
                <span style={styles.smallText}>Войти</span>
              </Link>
              <Link 
                to="/register" 
                style={{
                  ...styles.smallButton,
                  ...(isActive('/register') ? styles.activeSmallButton : {})
                }}
              >
                <span style={styles.smallIcon}>📝</span>
                <span style={styles.smallText}>Регистрация</span>
              </Link>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

// Инлайн стили для максимального контроля
const styles = {
  header: {
    position: 'fixed' as 'fixed',
    top: 0,
    left: 0,
    right: 0,
    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
    padding: '15px 30px',
    boxShadow: '0 6px 30px rgba(0, 0, 0, 0.4)',
    zIndex: 10000,
    borderBottom: '4px solid rgba(255, 255, 255, 0.3)',
    height: '100px',
    display: 'flex',
    alignItems: 'center',
  },
  container: {
    width: '100%',
    maxWidth: '2000px',
    margin: '0 auto',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    height: '100%',
  },
  logoLink: {
    textDecoration: 'none',
    flexShrink: 0 as 0,
  },
  logo: {
    fontSize: '3rem',
    fontWeight: 900,
    color: 'white',
    padding: '15px 25px',
    background: 'rgba(255, 255, 255, 0.25)',
    borderRadius: '20px',
    border: '5px solid rgba(255, 255, 255, 0.4)',
    textShadow: '3px 3px 8px rgba(0, 0, 0, 0.5)',
    letterSpacing: '3px',
    boxShadow: '0 8px 25px rgba(0, 0, 0, 0.3)',
    transition: 'all 0.3s ease',
    minWidth: '300px',
    textAlign: 'center' as 'center',
    display: 'inline-block',
  },
  centerNav: {
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    gap: '60px',
    flex: 1,
    margin: '0 50px',
  },
  megaButton: {
    textDecoration: 'none',
    padding: '25px 50px',
    fontSize: '2.8rem',
    fontWeight: 900,
    color: 'white',
    background: 'rgba(255, 255, 255, 0.3)',
    border: '6px solid rgba(255, 255, 255, 0.4)',
    borderRadius: '30px',
    display: 'flex',
    alignItems: 'center',
    gap: '25px',
    minWidth: '350px',
    justifyContent: 'center',
    boxShadow: '0 15px 35px rgba(0, 0, 0, 0.4)',
    transition: 'all 0.3s ease',
    textShadow: '2px 2px 6px rgba(0, 0, 0, 0.4)',
    letterSpacing: '2px',
  },
  activeMegaButton: {
    background: 'rgba(255, 255, 255, 0.4)',
    borderColor: '#ffd700',
    boxShadow: '0 20px 40px rgba(0, 0, 0, 0.5), inset 0 0 30px rgba(255, 255, 255, 0.3)',
  },
  megaIcon: {
    fontSize: '4rem',
  },
  megaText: {
    fontSize: '3rem',
    fontWeight: 900,
  },
  rightSection: {
    display: 'flex',
    alignItems: 'center',
    gap: '40px',
    flexShrink: 0 as 0,
  },
  smallButton: {
    textDecoration: 'none',
    padding: '18px 30px',
    fontSize: '1.8rem',
    fontWeight: 700,
    color: 'white',
    background: 'rgba(255, 255, 255, 0.2)',
    border: '4px solid rgba(255, 255, 255, 0.3)',
    borderRadius: '20px',
    display: 'flex',
    alignItems: 'center',
    gap: '15px',
    minWidth: '200px',
    justifyContent: 'center',
    transition: 'all 0.3s ease',
    textShadow: '1px 1px 3px rgba(0, 0, 0, 0.3)',
  },
  activeSmallButton: {
    background: 'rgba(255, 255, 255, 0.35)',
    borderColor: 'rgba(255, 255, 255, 0.45)',
  },
  smallIcon: {
    fontSize: '2.2rem',
  },
  smallText: {
    fontSize: '1.8rem',
    fontWeight: 700,
  },
  userBlock: {
    display: 'flex',
    alignItems: 'center',
    gap: '30px',
    paddingLeft: '30px',
    borderLeft: '5px solid rgba(255, 255, 255, 0.3)',
  },
  userInfo: {
    display: 'flex',
    alignItems: 'center',
    gap: '20px',
    padding: '15px 25px',
    background: 'rgba(255, 255, 255, 0.2)',
    borderRadius: '20px',
    border: '4px solid rgba(255, 255, 255, 0.3)',
    fontSize: '1.8rem',
  },
  userIcon: {
    fontSize: '2.5rem',
  },
  userName: {
    fontWeight: 700,
    fontSize: '1.8rem',
    color: 'white',
  },
  adminTag: {
    background: 'linear-gradient(45deg, #ffd700, #ffaa00)',
    color: '#000',
    padding: '8px 15px',
    borderRadius: '25px',
    fontSize: '1rem',
    fontWeight: 900,
    border: '3px solid rgba(255, 255, 255, 0.6)',
    boxShadow: '0 4px 10px rgba(0, 0, 0, 0.3)',
  },
  userActions: {
    display: 'flex',
    gap: '20px',
  },
  profileButton: {
    padding: '18px 35px',
    fontSize: '1.8rem',
    fontWeight: 700,
    background: 'linear-gradient(135deg, #48bb78, #38a169)',
    color: 'white',
    border: '4px solid rgba(255, 255, 255, 0.3)',
    borderRadius: '20px',
    cursor: 'pointer',
    transition: 'all 0.3s ease',
    minWidth: '180px',
    letterSpacing: '1px',
    textShadow: '1px 1px 3px rgba(0, 0, 0, 0.3)',
  },
  logoutButton: {
    padding: '18px 35px',
    fontSize: '1.8rem',
    fontWeight: 700,
